  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Những giọng hát khác nhau\":\nLớp 4A chuẩn bị cho buổi văn nghệ. Cô giáo cho mỗi bạn hát thử một đoạn. Giọng Lan trong veo như tiếng suối. Giọng Hùng trầm ấm. Giọng Mai cao vút, còn Tuấn hát hơi run vì ngại. Cô mỉm cười: \"Mỗi em một giọng, nhưng khi hoà vào nhau sẽ thành một dàn đồng ca thật đẹp.\" Cả lớp tập luyện suốt hai tuần. Đến ngày biểu diễn, tiếng hát của cả lớp vang lên hài hoà, ai nghe cũng vỗ tay. Tuấn không còn run nữa, cậu hát to và tự tin.\n\nGiọng hát của Lan được so sánh với gì?"}'::jsonb, '["tiếng suối","tiếng sáo","tiếng chim"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
