  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Hai anh em sinh đôi\":\nNam và Việt là anh em sinh đôi, giống nhau như hai giọt nước. Thầy cô thường gọi nhầm tên hai bạn. Nhưng tính nết hai anh em lại khác hẳn. Nam thích đọc sách, ít nói, hay ngồi vẽ bản đồ. Việt hiếu động, mê đá bóng và rất giỏi kể chuyện cười. Có lần trường tổ chức thi tìm hiểu về Hà Nội, Nam lo phần kiến thức, Việt lo thuyết trình. Đội của hai anh em giành giải nhất. Từ đó, cả lớp không còn chỉ nhìn khuôn mặt để phân biệt hai bạn nữa.\n\nNam và Việt giống nhau ở điểm nào?"}'::jsonb, '["khuôn mặt","tính nết","sở thích"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
