  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Cô bé đánh trống\":\nThảo là cô bé nhỏ nhất đội nghi thức của trường. Nhiều người nghĩ em không thể đánh trống. Thảo không nản. Chiều nào em cũng ở lại sân trường tập gõ nhịp lên mặt ghế. Đôi tay em có lúc mỏi nhừ nhưng em vẫn kiên trì. Đến lễ khai giảng, tiếng trống của Thảo vang lên rộn rã, đều tay. Thầy hiệu trưởng khen: \"Em nhỏ người nhưng có trái tim của một nghệ sĩ thực thụ!\"\n\nThảo là ai trong đội nghi thức?"}'::jsonb, '["cô bé nhỏ nhất đội","đội trưởng","người lớn tuổi nhất"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
