  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Chuyến thăm Thư viện Quốc gia\":\nThứ bảy vừa rồi, lớp em được đến thăm Thư viện Quốc gia Việt Nam. Cô thủ thư dẫn chúng em đi qua những giá sách cao tới trần nhà. Cô kể thư viện lưu giữ hàng triệu cuốn sách, báo, có những cuốn đã hơn trăm năm tuổi. Chúng em được xem phòng đọc dành cho thiếu nhi và học cách tra cứu sách bằng máy tính. Lúc ra về, ai cũng mong được quay lại để đọc thật nhiều sách hay.\n\nLớp em đến thăm nơi nào?"}'::jsonb, '["Thư viện Quốc gia Việt Nam","Bảo tàng Lịch sử","Nhà văn hoá Thiếu nhi"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
