  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Quả trứng nở\":\nBà cho Minh xem ổ trứng gà sắp nở. Minh hồi hộp ngồi canh suốt buổi sáng. Bỗng một quả trứng khẽ rung. Từ bên trong, chiếc mỏ nhỏ xíu mổ \"cốc, cốc\" vào vỏ. Vỏ trứng nứt dần. Rồi một chú gà con ướt lông chui ra, run run đứng dậy. Chỉ một lúc sau, lông chú khô, xù lên như cục bông vàng. Chú kêu \"chiếp chiếp\", lạch bạch chạy theo gà mẹ. Minh reo lên: \"Bà ơi, cả một thế giới vừa mở ra trong quả trứng!\"\n\nMinh ngồi canh ổ trứng vào lúc nào?"}'::jsonb, '["buổi sáng","buổi tối","buổi trưa"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
