  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Chiếc máy tưới cây của Bin\":\nBin rất thích các chậu hoa trên ban công nhưng hay quên tưới nước. Một hôm, Bin nghĩ ra cách: lấy chai nhựa cũ, đục mấy lỗ nhỏ ở nắp rồi cắm ngược chai đầy nước xuống chậu. Nước rỉ ra từng giọt, thấm dần vào đất. Mấy ngày sau, hoa vẫn tươi tốt. Bố khen Bin là \"nhà phát minh nhí\". Bin còn hướng dẫn các bạn trong lớp làm theo để tưới cây ở vườn trường.\n\nBin hay quên làm việc gì?"}'::jsonb, '["tưới nước cho cây","làm bài tập","dọn phòng"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
