  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Cuốn từ điển của ông\":\nÔng nội có một cuốn từ điển dày, bìa đã sờn. Một hôm, Hà gặp từ \"kiên định\" mà không hiểu nghĩa. Ông bảo Hà tự tra. Hà lật đến phần chữ K, rồi tìm theo thứ tự chữ cái tiếp theo: \"ki\", \"kiê\", \"kiên\"... Cuối cùng em tìm thấy: kiên định nghĩa là giữ vững ý định, không thay đổi. Ông cười: \"Từ điển là người thầy không bao giờ mệt. Cháu càng tra nhiều, vốn từ càng giàu.\"\n\nHà gặp từ nào mà không hiểu nghĩa?"}'::jsonb, '["kiên định","kiên nhẫn","quyết tâm"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
