  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Hộp màu biết nói\":\nMai có một hộp bút màu mới. Đêm ấy, Mai mơ thấy các bút màu trò chuyện. Chị Xanh Lá khoe: \"Tớ tô cho cánh đồng mượt mà.\" Anh Vàng tự hào: \"Tớ làm cho ông mặt trời rạng rỡ.\" Bé Đỏ thì thầm: \"Tớ nhuộm hồng đôi má em bé.\" Bác Đen lặng lẽ nói: \"Thiếu tớ, bức tranh đêm chẳng có sao lấp lánh.\" Sáng hôm sau, Mai vẽ một bức tranh có đủ mọi màu. Mai hiểu rằng màu nào cũng đáng quý.\n\nChị Xanh Lá tô cho cái gì?"}'::jsonb, '["cánh đồng","mặt trời","đôi má em bé"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
