  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Ước mơ chế tạo tên lửa\":\nTừ nhỏ, cậu bé Khoa đã mê bầu trời đầy sao. Cậu hay hỏi: \"Làm sao để bay lên các vì sao?\" Khoa đọc rất nhiều sách về thiên văn, tự làm những chiếc tên lửa bằng giấy, bằng ống nhựa. Nhiều lần tên lửa rơi ngay khi vừa bay lên. Khoa không nản, kiên trì sửa từng chi tiết. Cuối cùng, chiếc tên lửa nước của cậu bay cao hơn mái nhà. Khoa thầm hứa sẽ học thật giỏi để thực hiện ước mơ lớn.\n\nKhoa mê điều gì từ nhỏ?"}'::jsonb, '["bầu trời đầy sao","đá bóng","trồng cây"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
