  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Ước mơ làm phi công\":\nMỗi lần nghe tiếng máy bay, Duy lại chạy ra sân ngước nhìn. Duy mơ ước trở thành phi công, lái những chiếc máy bay to lớn bay qua nhiều đất nước. Bố bảo muốn làm phi công phải có sức khoẻ tốt, học giỏi và bình tĩnh. Từ đó, sáng nào Duy cũng dậy sớm chạy bộ, chăm chỉ học Toán và Tiếng Anh. Duy tin rằng ước mơ sẽ thành hiện thực nếu mình nỗ lực từng ngày.\n\nDuy đã làm gì để theo đuổi ước mơ?"}'::jsonb, '["Dậy sớm chạy bộ, chăm học Toán và Tiếng Anh","Chỉ ngồi xem máy bay","Bỏ học để chơi"]'::jsonb, null, 4, 70, 6, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.03')) returning id into v_q;
