  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Lá thư gửi năm 2050\":\nLớp 4C viết thư gửi chính mình của năm 2050. Phương viết: \"Chào Phương của tương lai! Tớ mong cậu đã trở thành bác sĩ, chữa bệnh cho trẻ em vùng cao.\" Hải viết về ước mơ làm kĩ sư, xây những cây cầu nối các làng ven sông. Cô giáo cất những lá thư vào một chiếc hộp, hẹn hai mươi năm sau cả lớp sẽ cùng mở. Ai cũng háo hức nghĩ về chuyến hành trình – từ hôm nay đến tương lai.\n\nLớp 4C viết thư gửi ai?"}'::jsonb, '["chính mình của năm 2050","các bạn lớp khác","thầy hiệu trưởng"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
