  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Nếu tớ có phép lạ\":\nGiờ ra chơi, nhóm bạn ngồi dưới gốc phượng kể về điều sẽ làm nếu có phép lạ. Hưng muốn những hạt giống nảy mầm thành rừng xanh trên đồi trọc. Vy muốn mọi bạn nhỏ đều được đến trường. Bảo muốn chế ra chiếc máy biến rác thành đồ chơi. Cuối cùng, cả nhóm nhận ra: có những điều không cần phép lạ, chỉ cần mình chăm chỉ học tập và chung tay làm từ hôm nay.\n\nNhóm bạn ngồi ở đâu?"}'::jsonb, '["dưới gốc phượng","trong thư viện","ngoài cổng trường"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
