  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Cây bút chì nhỏ\":\nTrong hộp bút của Nam có một cây bút chì đã mòn chỉ còn ngắn bằng ngón tay. Các bạn bút mới chê nó: \"Cậu xấu xí quá!\" Bút chì nhỏ buồn lắm. Nhưng Nam vẫn giữ nó cẩn thận. Nam bảo: \"Cây bút này đã cùng tớ viết những bài văn đầu tiên, vẽ những bức tranh đầu tiên.\" Nghe vậy, bút chì nhỏ thấy ấm lòng. Nó hiểu giá trị của mình nằm ở những điều đã làm được.\n\nCây bút chì của Nam thế nào?"}'::jsonb, '["đã mòn, chỉ còn ngắn bằng ngón tay","mới tinh","gãy đôi"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V4.DOC.01')) returning id into v_q;
